ee:message.ee:set-payload:
%dw 2.0
output application/json
import modules::GlobalFunctions as global
var additionalDate = vars.getIdentityResponse.result[0].fecha_exp default null
var formattedDate = global::formatDateToISO8601(additionalDate)
---
{
	"query": {
		"update": "MDM_VALIDACION_CLIENTE",
		"updates": [{
			"q": {
				"num_doc": vars.initialPayload.documentNumber,
				"tipo_doc": vars.initialPayload.documentType
			},
			"u": [{
				"\$set": {
					"fecha_consulta": global::formatDate(now() >> "UTC-05:00" as TimeZone),
					"fecha_exp": {
						"\$concat": [formattedDate[0 to 9],
                                    formattedDate[10 to -1]]
					},
					"causal": vars.rsLisim.cause default vars.rsLisim.message default ""
				}
			}],
			"multi": false,
			"upsert": false
		}]
	}
}

%dw 2.0
output application/json
---
{
  code: "200",
  message: vars.rsLisim.cause default vars.rsLisim.message default "validacion exitosa",
  result: {}
}

%dw 2.0
output application/json
import modules::GlobalFunctions as global
var formattedDate = global::formatDateToISO8601(vars.initialPayload.dateExpedition)
---
{
	"query": {
		"aggregate": 1,
		"pipeline": [{
			"\$documents": [{
				"nombres": vars.initialPayload.names,
				"apellido": vars.initialPayload.firstLastName,
				"segundo_apellido": vars.initialPayload.secondLastName,
				"num_doc": vars.initialPayload.documentNumber,
				"tipo_doc": vars.initialPayload.documentType,
				"fecha_consulta": global::formatDate(now() >> "UTC-05:00" as TimeZone),
				"estado": "NO VIGENTE",
				"causal": vars.rsLisim.cause default vars.rsLisim.message default ""
			}]
		},
            {
			"\$set": {
				"fecha_exp": {
					"\$concat": [
						formattedDate[0 to 9],
                        formattedDate[10 to -1]]
				}
			}
		},
            {
			"\$merge": {
				"into": "MDM_VALIDACION_CLIENTE",
				"whenMatched": "fail",
				"whenNotMatched": "insert"
			}
		}],
		"cursor": {
		}
	}
}

%dw 2.0
output application/json
---
{
  code: "200",
  message: vars.rsLisim.cause default vars.rsLisim.message default "validacion exitosa",
  result: {}
}
